import json,random,subprocess,statistics,math,os
os.sched_setaffinity(0,{min(os.sched_getaffinity(0))})
from pathlib import Path
bins={"baseline":"/work/benchmarks/.build/benchmark","candidate":"/candidate/benchmarks/.build/benchmark"}
profile="many-generators"
paths={name:"/candidate/atemp/query-"+name for name in bins}
def invoke(name,op):
 return json.loads(subprocess.check_output([bins[name],op,"vtr",profile,paths[name],"1"],text=True))
oracle=invoke("baseline","oracle")["find-transaction"]
for name in bins:invoke(name,"write")
rng=random.Random(20261111);rows=[]
for repeat in range(60):
 order=list(bins);rng.shuffle(order)
 for name in order:
  result=invoke(name,"find-transaction")
  assert result["digests"]==oracle
  rows.append(dict(variant=name,repeat=repeat,**result))
Path("/src/atemp/intern-query-tail.json").write_text(json.dumps(rows,indent=2)+"\n")
for name in bins:
 values=sorted(t for row in rows if row["variant"]==name for t in row["latencies_seconds"])
 print(name,"p50_ms",statistics.median(values)*1000,"p95_ms",values[math.ceil(len(values)*.95)-1]*1000,"probes",len(values))
